1	//! Derived CLI definition covering nested subcommands, global arguments, and
2	//! failure recovery. Everything is observed through `Cli::try_parse_from`
3	//! with token sequences that include argv0.
4	#![allow(unreachable_pub)] // types stay observable to sibling test modules
5	
6	use clap::Args;
7	use clap::Parser;
8	use clap::Subcommand;
9	
10	fn parse_port(raw: &str) -> Result<u16, String> {
11	    let value: u64 = raw
12	        .parse()
13	        .map_err(|_| format!("invalid port `{raw}`: expected a decimal integer"))?;
14	    if (1..=65535).contains(&value) {
15	        Ok(value as u16)
16	    } else {
17	        Err(format!(
18	            "invalid port `{raw}`: must be between 1 and 65535"
19	        ))
20	    }
21	}
22	
23	#[derive(Parser, Debug, PartialEq)]
24	#[command(
25	    name = "tool",
26	    about = "Root command with global options",
27	    override_usage = "tool [OPTIONS] <COMMAND>"
28	)]
29	pub struct Cli {
30	    #[arg(long, global = true, default_value = "builtin.toml", value_name = "path")]
31	    pub config: String,
32	    #[arg(long, global = true, value_name = "key=value")]
33	    pub define: Vec<String>,
34	    #[command(subcommand)]
35	    pub command: Commands,
36	}
37	
38	#[derive(Subcommand, Debug, PartialEq)]
39	pub enum Commands {
40	    #[command(about = "Run the server")]
41	    Serve(ServeArgs),
42	    #[command(about = "Check a path")]
43	    Check(CheckArgs),
44	}
45	
46	#[derive(Args, Debug, PartialEq)]
47	#[command(override_usage = "tool serve [OPTIONS] <COMMAND>")]
48	pub struct ServeArgs {
49	    #[arg(long)]
50	    pub profile: Option<String>,
51	    #[command(subcommand)]
52	    pub command: ServeCommands,
53	}
54	
55	#[derive(Subcommand, Debug, PartialEq)]
56	pub enum ServeCommands {
57	    #[command(about = "Run a worker")]
58	    Worker(WorkerArgs),
59	}
60	
61	#[derive(Args, Debug, PartialEq)]
62	#[command(
63	    group = clap::ArgGroup::new("protocol").args(["http", "https"]).multiple(false),
64	    override_usage = "tool serve worker [OPTIONS] --port <PORT> [-- <TRAILING>...]"
65	)]
66	pub struct WorkerArgs {
67	    #[arg(long, value_parser = parse_port)]
68	    pub port: u16,
69	    #[arg(long, help = "Serve plain HTTP (mutually exclusive with --https)")]
70	    pub http: bool,
71	    #[arg(long, help = "Serve HTTPS (mutually exclusive with --http)")]
72	    pub https: bool,
73	    #[arg(last = true)]
74	    pub trailing: Vec<String>,
75	}
76	
77	#[derive(Args, Debug, PartialEq)]
78	#[command(override_usage = "tool check [OPTIONS] [path]")]
79	pub struct CheckArgs {
80	    pub path: Option<String>,
81	    #[arg(long)]
82	    pub strict: bool,
83	}
84	
85	#[cfg(test)]
86	mod tests {
87	    use super::*;
88	    use clap::error::ErrorKind;
89	
90	    fn parse(argv: &[&str]) -> Result<Cli, clap::Error> {
91	        Cli::try_parse_from(argv)
92	    }
93	
94	    fn worker_ok(argv: &[&str]) -> (Cli, WorkerArgs) {
95	        let cli = parse(argv).unwrap();
96	        let Cli {
97	            command: Commands::Serve(ServeArgs {
98	                command: ServeCommands::Worker(ref worker),
99	                ..
100	            }),
101	            ..
102	        } = cli
103	        else {
104	            panic!("expected `serve worker` parse");
105	        };
106	        let worker = WorkerArgs {
107	            port: worker.port,
108	            http: worker.http,
109	            https: worker.https,
110	            trailing: worker.trailing.clone(),
111	        };
112	        (cli, worker)
113	    }
114	
115	    #[test]
116	    fn minimal_worker_parse() {
117	        let (cli, worker) = worker_ok(&["tool", "serve", "worker", "--port", "8080"]);
118	        assert_eq!(cli.config, "builtin.toml");
119	        assert_eq!(cli.define, Vec::<String>::new());
120	        assert_eq!(worker.port, 8080);
121	        assert!(!worker.http && !worker.https);
122	        assert_eq!(worker.trailing, Vec::<String>::new());
123	    }
124	
125	    #[test]
126	    fn explicit_config_overrides_default() {
127	        let (cli, _) = worker_ok(&[
128	            "tool", "--config", "custom.toml", "serve", "worker", "--port", "1",
129	        ]);
130	        assert_eq!(cli.config, "custom.toml");
131	    }
132	
133	    #[test]
134	    fn defines_preserve_order() {
135	        let (cli, _) = worker_ok(&[
136	            "tool",
137	            "--define",
138	            "b=2",
139	            "serve",
140	            "--define",
141	            "a=1",
142	            "worker",
143	            "--port",
144	            "1",
145	            "--define",
146	            "c=3",
147	        ]);
148	        assert_eq!(cli.define, vec!["b=2", "a=1", "c=3"]);
149	    }
150	
151	    #[test]
152	    fn global_args_accepted_at_any_position() {
153	        let expected = worker_ok(&[
154	            "tool", "--config", "x.toml", "--define", "k=v", "serve", "worker", "--port", "9",
155	        ]);
156	        for argv in [
157	            &["tool", "serve", "--config", "x.toml", "worker", "--define", "k=v", "--port", "9"][..],
158	            &["tool", "serve", "worker", "--port", "9", "--config", "x.toml", "--define", "k=v"][..],
159	            &["tool", "serve", "worker", "--config", "x.toml", "--port", "9", "--define", "k=v"][..],
160	        ] {
161	            assert_eq!(parse(argv).unwrap(), expected.0);
162	        }
163	    }
164	
165	    #[test]
166	    fn port_bounds() {
167	        assert_eq!(worker_ok(&["tool", "serve", "worker", "--port", "1"]).1.port, 1);
168	        assert_eq!(
169	            worker_ok(&["tool", "serve", "worker", "--port", "65535"]).1.port,
170	            65535
171	        );
172	    }
173	
174	    #[test]
175	    fn protocol_flags_are_exclusive() {
176	        let (_, worker) = worker_ok(&["tool", "serve", "worker", "--port", "1", "--http"]);
177	        assert!(worker.http && !worker.https);
178	        let (_, worker) = worker_ok(&["tool", "serve", "worker", "--port", "1", "--https"]);
179	        assert!(worker.https && !worker.http);
180	    }
181	
182	    #[test]
183	    fn trailing_tokens_after_double_dash_are_raw() {
184	        let (cli, worker) = worker_ok(&[
185	            "tool", "serve", "worker", "--port", "1", "--", "--config", "serve", "check",
186	            "--http", "--",
187	        ]);
188	        assert_eq!(
189	            worker.trailing,
190	            vec!["--config", "serve", "check", "--http", "--"]
191	        );
192	        // Tokens after `--` must not be interpreted as global args.
193	        assert_eq!(cli.config, "builtin.toml");
194	    }
195	
196	    #[test]
197	    fn unknown_token_before_separator_fails_at_worker() {
198	        let err = parse(&["tool", "serve", "worker", "--port", "1", "--bogus"]).unwrap_err();
199	        assert_eq!(err.kind(), ErrorKind::UnknownArgument);
200	        let msg = err.to_string();
201	        assert!(msg.contains("--bogus"), "{msg}");
202	        assert!(msg.contains("tool serve worker"), "{msg}");
203	    }
204	
205	    #[test]
206	    fn check_parses_optional_path_and_strict() {
207	        let cli = parse(&["tool", "check"]).unwrap();
208	        let Commands::Check(check) = cli.command else {
209	            panic!("expected check");
210	        };
211	        assert_eq!(check.path, None);
212	        assert!(!check.strict);
213	
214	        let cli = parse(&["tool", "check", "some/path", "--strict"]).unwrap();
215	        let Commands::Check(check) = cli.command else {
216	            panic!("expected check");
217	        };
218	        assert_eq!(check.path.as_deref(), Some("some/path"));
219	        assert!(check.strict);
220	    }
221	
222	    #[test]
223	    fn check_treats_post_separator_token_as_path() {
224	        let cli = parse(&["tool", "check", "--", "--strict"]).unwrap();
225	        let Commands::Check(check) = cli.command else {
226	            panic!("expected check");
227	        };
228	        assert_eq!(check.path.as_deref(), Some("--strict"));
229	        assert!(!check.strict);
230	
231	        let err = parse(&["tool", "check", "--", "a", "b"]).unwrap_err();
232	        assert_eq!(err.kind(), ErrorKind::UnknownArgument);
233	    }
234	
235	    #[test]
236	    fn check_rejects_serve_and_worker_args() {
237	        for argv in [
238	            &["tool", "check", "--profile", "p"][..],
239	            &["tool", "check", "--port", "1"][..],
240	            &["tool", "check", "--http"][..],
241	        ] {
242	            let err = parse(argv).unwrap_err();
243	            assert_eq!(err.kind(), ErrorKind::UnknownArgument, "{argv:?}");
244	        }
245	    }
246	
247	    #[test]
248	    fn missing_port_fails() {
249	        let err = parse(&["tool", "serve", "worker"]).unwrap_err();
250	        assert_eq!(err.kind(), ErrorKind::MissingRequiredArgument);
251	        let msg = err.to_string();
252	        assert!(msg.contains("--port"), "{msg}");
253	        assert!(msg.contains("tool serve worker"), "{msg}");
254	    }
255	
256	    #[test]
257	    fn invalid_ports_fail() {
258	        for bad in ["0", "65536", "abc", "1.5", "0x10"] {
259	            let err = parse(&["tool", "serve", "worker", "--port", bad]).unwrap_err();
260	            assert_eq!(err.kind(), ErrorKind::ValueValidation, "{bad}");
261	            assert!(err.to_string().contains(bad), "{bad}");
262	        }
263	        // A leading hyphen makes the token an unknown flag rather than a value.
264	        assert!(parse(&["tool", "serve", "worker", "--port", "-1"]).is_err());
265	        let err = parse(&["tool", "serve", "worker", "--port=-1"]).unwrap_err();
266	        assert_eq!(err.kind(), ErrorKind::ValueValidation);
267	    }
268	
269	    #[test]
270	    fn conflicting_protocols_fail() {
271	        let err = parse(&["tool", "serve", "worker", "--port", "1", "--http", "--https"])
272	            .unwrap_err();
273	        assert_eq!(err.kind(), ErrorKind::ArgumentConflict);
274	    }
275	
276	    #[test]
277	    fn duplicate_values_fail() {
278	        for argv in [
279	            &["tool", "serve", "worker", "--port", "1", "--port", "2"][..],
280	            &["tool", "serve", "--profile", "a", "--profile", "b", "worker", "--port", "1"][..],
281	            &["tool", "serve", "worker", "--port", "1", "--http", "--http"][..],
282	        ] {
283	            assert!(parse(argv).is_err(), "{argv:?}");
284	        }
285	    }
286	
287	    #[test]
288	    fn unknown_subcommand_fails() {
289	        let err = parse(&["tool", "serv"]).unwrap_err();
290	        assert_eq!(err.kind(), ErrorKind::InvalidSubcommand);
291	        assert!(err.to_string().contains("serv"));
292	    }
293	
294	    #[test]
295	    fn missing_option_value_fails() {
296	        for argv in [
297	            &["tool", "--config"][..],
298	            &["tool", "serve", "--profile"][..],
299	            &["tool", "serve", "worker", "--port"][..],
300	            &["tool", "--define"][..],
301	        ] {
302	            let err = parse(argv).unwrap_err();
303	            assert_eq!(err.kind(), ErrorKind::InvalidValue, "{argv:?}");
304	        }
305	    }
306	
307	    #[test]
308	    fn failure_does_not_pollute_next_parse() {
309	        assert!(parse(&["tool", "serve", "worker"]).is_err());
310	        assert!(parse(&["tool", "serve", "worker", "--port", "abc"]).is_err());
311	        let (cli, worker) = worker_ok(&["tool", "serve", "worker", "--port", "80"]);
312	        assert_eq!(cli.config, "builtin.toml");
313	        assert_eq!(worker.port, 80);
314	    }
315	
316	    #[test]
317	    fn help_succeeds_at_every_level() {
318	        let root = parse(&["tool", "--help"]).unwrap_err();
319	        assert_eq!(root.kind(), ErrorKind::DisplayHelp);
320	        let root = root.to_string();
321	        for needle in ["--config", "--define", "builtin.toml", "serve", "check"] {
322	            assert!(root.contains(needle), "root help missing {needle}:\n{root}");
323	        }
324	        assert!(!root.contains("--profile"), "{root}");
325	        assert!(!root.contains("--port"), "{root}");
326	
327	        let serve = parse(&["tool", "serve", "--help"]).unwrap_err();
328	        assert_eq!(serve.kind(), ErrorKind::DisplayHelp);
329	        let serve = serve.to_string();
330	        for needle in ["--profile", "worker", "--config", "--define"] {
331	            assert!(serve.contains(needle), "serve help missing {needle}:\n{serve}");
332	        }
333	        assert!(!serve.contains("--port"), "{serve}");
334	        assert!(!serve.contains("--strict"), "{serve}");
335	
336	        // Required `--port` is missing, yet help must still succeed.
337	        let worker = parse(&["tool", "serve", "worker", "--help"]).unwrap_err();
338	        assert_eq!(worker.kind(), ErrorKind::DisplayHelp);
339	        let worker = worker.to_string();
340	        for needle in [
341	            "--port",
342	            "--http",
343	            "--https",
344	            "mutually exclusive with --https",
345	            "mutually exclusive with --http",
346	            "--config",
347	        ] {
348	            assert!(worker.contains(needle), "worker help missing {needle}:\n{worker}");
349	        }
350	        assert!(!worker.contains("--profile"), "{worker}");
351	        assert!(!worker.contains("--strict"), "{worker}");
352	
353	        let check = parse(&["tool", "check", "--help"]).unwrap_err();
354	        assert_eq!(check.kind(), ErrorKind::DisplayHelp);
355	        let check = check.to_string();
356	        for needle in ["--strict", "--config", "--define"] {
357	            assert!(check.contains(needle), "check help missing {needle}:\n{check}");
358	        }
359	        for absent in ["--profile", "--port", "--http"] {
360	            assert!(!check.contains(absent), "check help leaks {absent}:\n{check}");
361	        }
362	    }
363	
364	    #[test]
365	    fn global_position_swap_keeps_help_and_errors_stable() {
366	        let baseline = parse(&["tool", "--config", "x.toml", "serve", "worker", "--help"])
367	            .unwrap_err()
368	            .to_string();
369	        let swapped = parse(&["tool", "serve", "worker", "--config", "x.toml", "--help"])
370	            .unwrap_err()
371	            .to_string();
372	        assert_eq!(baseline, swapped);
373	
374	        let baseline = parse(&["tool", "--config", "x.toml", "serve", "worker"]).unwrap_err();
375	        let swapped = parse(&["tool", "serve", "worker", "--config", "x.toml"]).unwrap_err();
376	        assert_eq!(baseline.kind(), swapped.kind());
377	        assert_eq!(baseline.to_string(), swapped.to_string());
378	    }
379	}
